#[cfg(test)]
mod business_reject_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_business_reject_codec() {
        let original = BusinessReject {
            appl_id: "a".repeat(3),
            transact_time: -123456789,
            submitting_pbuid: "a".repeat(6),
            security_id: "a".repeat(8),
            security_id_source: "a".repeat(4),
            ref_seq_num: -123456789,
            ref_msg_type: 123456,
            business_reject_ref_id: "a".repeat(10),
            business_reject_reason: 1234,
            business_reject_text: "a".repeat(50),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(BusinessRejectRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        BusinessReject::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = BusinessReject::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

